export function getUmc2023Pages(start: number, end: number) {
  return umc2023ExactPages.filter((p) => p.pdfPage >= start && p.pdfPage <= end);
}

export function searchUmc2023Exact(query: string) {
  const q = query.trim().toLocaleLowerCase("vi-VN");
  if (!q) return [];
  return umc2023ExactPages.filter((p) => p.text.toLocaleLowerCase("vi-VN").includes(q));
}
